                        sftp.fastGet(fileSrc, fileDest, fpOptions, function (err) {
                          if (err) {
                            return callback(err);
                          }
                          grunt.verbose.writeln('download ' + fileSrc + ' to ' + fileDest);
                          tally.files++;
                          count--;
                          if (!count) {
                            callback();
                          }
                        });
                      };

